for(const b of document.querySelectorAll('[data-family]'))b.onclick=()=>{if(exporting)return;active=b.dataset.family;frameIndex=0;updateControls();schedule();};
function rgbaCanvas(rgb,w,h,mask){const c=makeCanvas(w,h),a=new Uint8ClampedArray(w*h*4);for(let i=0;i<w*h;i++){a[i*4]=rgb[i*3];a[i*4+1]=rgb[i*3+1];a[i*4+2]=rgb[i*3+2];a[i*4+3]=mask?mask[i]*255:255;}c.getContext('2d').putImageData(new ImageData(a,w,h),0,0);return c;}
function draw(target,im,zoom=1,grid=false){target.width=im.width*zoom;target.height=im.height*zoom;const ctx=target.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.drawImage(im,0,0,target.width,target.height);if(grid){ctx.strokeStyle='#ffffff40';ctx.lineWidth=1;for(let x=0;x<=im.width;x+=8){ctx.beginPath();ctx.moveTo(x*zoom+.5,0);ctx.lineTo(x*zoom+.5,target.height);ctx.stroke();}for(let y=0;y<=im.height;y++){ctx.beginPath();ctx.moveTo(0,y*zoom+.5);ctx.lineTo(target.width,y*zoom+.5);ctx.stroke();}}}
function inkBounds(r){let l=r.w,t=r.h,rr=-1,bb=-1;for(let y=0;y<r.h;y++)for(let x=0;x<r.w;x++){const k=(y*r.w+x)*3;if(r.rgb[k]||r.rgb[k+1]||r.rgb[k+2]){l=Math.min(l,x);t=Math.min(t,y);rr=Math.max(rr,x);bb=Math.max(bb,y);}}return rr<0?'empty':`${rr-l+1}×${bb-t+1} ink`;}
function paint(){const src=source(),i=frameIndex%src.frames.length,e=cache[active],r=e?.results[i],job=e?.jobs[i],zoom=Number($('zoom').value);draw($('original'),canvasFor(src.frames[i]),src.frames[i].w<=128&&src.frames[i].h<=128?zoom:1);$('originalSize').textContent=`${src.frames[i].w}×${src.frames[i].h}`;const cur=ART_DATA[active].current[i%ART_DATA[active].current.length],cr=bytes64(cur.rgba),cm=Uint8Array.from({length:cur.w*cur.h},(_,n)=>+(cr[n*4]||cr[n*4+1]||cr[n*4+2]));const cc=canvasFor(cur);const ccur=makeCanvas(cur.w,cur.h);ccur.getContext('2d').drawImage(cc,0,0);let image=ccur.getContext('2d').getImageData(0,0,cur.w,cur.h);for(let n=0;n<cm.length;n++)image.data[n*4+3]=cm[n]*255;ccur.getContext('2d').putImageData(image,0,0);draw($('current'),ccur,zoom);$('currentSize').textContent=cur.label;
 if(job){draw($('scaled'),rgbaCanvas(job.preparedRaw,job.w,job.h,job.preparedMask),zoom);$('scaledSize').textContent=`${job.w}×${job.h}`;}if(r){draw($('converted'),rgbaCanvas(r.rgb,r.w,r.h,job.preparedMask),zoom,$('grid').checked);$('resultSize').textContent=`${r.w}×${r.h} · ${inkBounds(r)}`;}else{$('converted').getContext('2d').clearRect(0,0,$('converted').width,$('converted').height);$('resultSize').textContent='Converting…';}
 $('frame').value=i;$('frameName').textContent=`${i+1} / ${src.frames.length} · ${src.frames[i].label}`;document.querySelectorAll('#filmstrip button').forEach((b,n)=>b.classList.toggle('selected',n===i));if(active==='snake'&&e?.complete)paintAssembly(e);}
function buildStrip(){const e=cache[active];$('filmstrip').replaceChildren();if(!e)return;e.results.forEach((r,i)=>{if(!r)return;const b=document.createElement('button');b.title=e.source.frames[i].label;const c=rgbaCanvas(r.rgb,r.w,r.h,e.jobs[i].preparedMask);c.style.width=r.w*3+'px';b.append(c);b.onclick=()=>{frameIndex=i;playing=false;$('play').textContent='Play animation';paint();};$('filmstrip').append(b);});}
function paintAssembly(e){const src=e.source,layout=src.assembly||Array.from({length:8},(_,i)=>({x:i*26,y:0,frame:i%e.results.length})),spacing=Number($('spacing').value)/100,minX=Math.min(...layout.map(v=>v.x)),minY=Math.min(...layout.map(v=>v.y));const w=e.settings.width,h=e.settings.height,positions=layout.map(o=>({x:Math.round((o.x-minX)*w/32*spacing),y:Math.round((o.y-minY)*h/32*spacing),frame:o.frame%e.results.length}));const c=makeCanvas(Math.max(...positions.map(p=>p.x))+w,Math.max(...positions.map(p=>p.y))+h),ctx=c.getContext('2d');for(const p of positions){const r=e.results[p.frame];ctx.drawImage(rgbaCanvas(r.rgb,r.w,r.h,e.jobs[p.frame].preparedMask),p.x,p.y);}const px=ctx.getImageData(0,0,c.width,c.height).data;let clashes=0;for(let y=0;y<c.height;y++)for(let x=0;x<c.width;x+=8){const set=new Set();for(let k=0;k<8&&x+k<c.width;k++){const at=(y*c.width+x+k)*4;set.add(px[at+3]?`${px[at]},${px[at+1]},${px[at+2]}`:'0,0,0');}if(set.size>2)clashes++;}draw($('assembly'),c,Math.max(1,Math.min(4,Math.floor(850/c.width))),$('assemblyGrid').checked);let stats=$('assemblyStats');if(!stats){stats=document.createElement('p');stats.id='assemblyStats';stats.className='hint';$('assembly').after(stats);}stats.textContent=`${layout.length} joints · ${src.assembly?'Captured arcade layout':'Illustrative layout; source has no captured orientation map'} · ${clashes} cells with more than two colours after overlap. This is an integration check, not a game renderer.`;$('spacingValue').textContent=Math.round(spacing*100)+'%';}
$('frame').oninput=()=>{frameIndex=Number($('frame').value);paint();};$('play').onclick=()=>{playing=!playing;$('play').textContent=playing?'Pause animation':'Play animation';};for(const id of ['zoom','grid','assemblyGrid','spacing'])$(id).oninput=paint;$('backdrop').onchange=()=>{document.body.classList.remove('checker','gray');if($('backdrop').value!=='black')document.body.classList.add($('backdrop').value);};
setInterval(()=>{if(playing&&performance.now()-lastTick>=Number($('speed').value)){lastTick=performance.now();frameIndex=(frameIndex+1)%source().frames.length;paint();}},30);
$('converted').onclick=e=>{const entry=cache[active],r=entry?.results[frameIndex];if(!r)return;const rect=$('converted').getBoundingClientRect(),x=Math.min(r.w-1,Math.floor((e.clientX-rect.left)/rect.width*r.w)),y=Math.min(r.h-1,Math.floor((e.clientY-rect.top)/rect.height*r.h)),a=r.attrs[y*r.w/8+(x>>3)];$('pixelInfo').textContent=`Pixel ${x},${y} · cell ${x>>3},${y} · INK ${names[a&7]} / PAPER ${names[(a>>3)&7]} · ${a&64?'BRIGHT':'normal'} · attribute ${a.toString(16).padStart(2,'0').toUpperCase()}`;};
function choices(){const d={schema:'rtype-l2-art-review/1',version:118,rpc:PROVENANCE,created:new Date().toISOString(),families:{},customSources:{}};for(const k of families){const src=source(k);d.families[k]={nativeDescriptors:ART_DATA[k].native,source:{id:src.id,label:src.label,provenance:src.provenance},settings:structuredClone(states[k]),decision:states[k].decision,notes:states[k].notes};if(src.local)d.customSources[k]=src;}return d;}
function download(name,blob){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),15000);}
$('save').onclick=()=>download('rtype-l2-art-choices.json',new Blob([JSON.stringify(choices(),null,2)],{type:'application/json'}));
$('import').onchange=async()=>{try{const f=$('import').files[0];if(!f)return;const doc=JSON.parse(await f.text());if(doc.schema!=='rtype-l2-art-review/1'||!doc.families)throw Error('This is not a converter choices file');for(const k of families){const c=doc.customSources?.[k];if(c){if(!Array.isArray(c.frames)||c.frames.length>64||!c.frames.length||c.frames.some(f=>!Number.isInteger(f.w)||!Number.isInteger(f.h)||f.w<1||f.h<1||f.w*f.h>4194304||bytes64(f.rgba).length!==f.w*f.h*4))throw Error('Invalid custom source');c.local=true;ART_DATA[k].sources=ART_DATA[k].sources.filter(s=>s.id!==c.id);ART_DATA[k].sources.push(c);}if(doc.families[k])states[k]=clean(k,doc.families[k].settings);}cache={};frameIndex=0;updateControls();schedule();status('Choices imported; converting…');}catch(e){status(e.message,true);}};
$('sourceFile').onchange=async()=>{try{const file=$('sourceFile').files[0];if(!file)return;const cols=Math.max(1,Math.min(16,Number($('sheetCols').value)||1)),rows=Math.max(1,Math.min(16,Number($('sheetRows').value)||1));if(!Number.isInteger(cols)||!Number.isInteger(rows)||cols*rows>64)throw Error('Use at most64whole frames');const bmp=await createImageBitmap(file),w=Math.floor(bmp.width/cols),h=Math.floor(bmp.height/rows);if(!w||!h||w*h>4194304)throw Error('Sprite-sheet frame dimensions are too large or empty');const frames=[];for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){const c=makeCanvas(w,h);c.getContext('2d').drawImage(bmp,x*w,y*h,w,h,0,0,w,h);frames.push({w,h,rgba:to64(c.getContext('2d').getImageData(0,0,w,h).data),label:`${file.name} · ${frames.length+1}`});}bmp.close();const s={id:'custom',label:file.name,provenance:'Local image supplied in this editor; no arcade identity inferred.',local:true,frames};ART_DATA[active].sources=ART_DATA[active].sources.filter(s=>s.id!=='custom');ART_DATA[active].sources.push(s);Object.assign(states[active],{source:'custom',cropX:0,cropY:0,cropW:0,cropH:0,trim:true,blackCutout:true});frameIndex=0;updateControls();schedule();}catch(e){status(e.message,true);}};
const pngBytes=canvas=>new Promise((resolve,reject)=>canvas.toBlob(async b=>b?resolve(new Uint8Array(await b.arrayBuffer())):reject(Error('PNG export failed')),'image/png'));
$('png').onclick=async()=>{clearTimeout(debounce);try{const e=await convertFamily(active),r=e.results[frameIndex];download(`L1_${active}_${frameIndex}.png`,new Blob([await pngBytes(rgbaCanvas(r.rgb,r.w,r.h,e.jobs[frameIndex].preparedMask))],{type:'image/png'}));}catch(e){if(e.name!=='AbortError')status(e.message,true);}};
const crcTable=Uint32Array.from({length:256},(_,n)=>{let c=n;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;return c>>>0;});function crc32(a){let c=0xffffffff;for(const n of a)c=crcTable[(c^n)&255]^(c>>>8);return(c^0xffffffff)>>>0;}
function zipStore(files){const enc=new TextEncoder(),parts=[],central=[];let offset=0;for(const f of files){const name=enc.encode(f.name),data=f.data,crc=crc32(data),head=new Uint8Array(30),v=new DataView(head.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);parts.push(head,name,data);const c=new Uint8Array(46),d=new DataView(c.buffer);d.setUint32(0,0x02014b50,true);d.setUint16(4,20,true);d.setUint16(6,20,true);d.setUint16(8,0x800,true);d.setUint32(16,crc,true);d.setUint32(20,data.length,true);d.setUint32(24,data.length,true);d.setUint16(28,name.length,true);d.setUint32(42,offset,true);central.push(c,name);offset+=head.length+name.length+data.length;}const len=central.reduce((n,a)=>n+a.length,0),end=new Uint8Array(22),v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,files.length,true);v.setUint16(10,files.length,true);v.setUint32(12,len,true);v.setUint32(16,offset,true);return new Blob([...parts,...central,end],{type:'application/zip'});}
async function buildZip(){const files=[],manifest=choices(),enc=new TextEncoder();for(const k of families){const e=await convertFamily(k),sheet=makeCanvas(e.settings.width*e.results.length,e.settings.height),ctx=sheet.getContext('2d');manifest.families[k].crop=e.crop;manifest.families[k].frames=[];for(let i=0;i<e.results.length;i++){const r=e.results[i],name=`${k}/frame_${String(i).padStart(2,'0')}`,c=rgbaCanvas(r.rgb,r.w,r.h,e.jobs[i].preparedMask),pairs=new Uint8Array(r.bits.length*2);let at=0;for(let x=0;x<r.w/8;x++)for(let y=0;y<r.h;y++){pairs[at++]=r.bits[y*r.w/8+x];pairs[at++]=r.attrs[y*r.w/8+x];}ctx.drawImage(c,i*r.w,0);for(const[ext,data]of [['png',await pngBytes(c)],['bits.bin',r.bits],['attrs.bin',r.attrs],['preserve.bin',r.preserve],['pairs.bin',pairs]])files.push({name:name+'.'+ext,data});manifest.families[k].frames.push({frame:i,label:e.source.frames[i].label,width:r.w,height:r.h,visible:inkBounds(r),pairBytes:pairs.length,legal8x1:true});}files.push({name:`${k}/sheet.png`,data:await pngBytes(sheet)});}files.push({name:'choices.json',data:enc.encode(JSON.stringify(manifest,null,2))},{name:'README.txt',data:enc.encode('R-Type L1 artwork export. Offline artwork, not installed gameplay.\nAll settings are shared per animation family. .bits/.attrs/.preserve are row-major; .pairs is column-major bitmap/attribute row pairs. Mask bit1 preserves background. Black space is normal black. No flash.\nCheck preshift/overlap/collision and RAM placement before integration. Source/provenance and exact settings are in choices.json.\n')});return zipStore(files);}
function setExportBusy(v){exporting=v;$('controls').disabled=v;for(const id of ['zip','png','save','import'])$(id).disabled=v;document.querySelectorAll('[data-family]').forEach(b=>b.disabled=v);$('zip').textContent=v?'Building ghost pack…':'Export ghost asset pack';}
$('zip').onclick=async()=>{clearTimeout(debounce);setExportBusy(true);try{const blob=await buildZip();download('rtype-l2-art-assets.zip',blob);status('L2 asset pack exported. Game files unchanged.');}catch(e){status(e.message,true);}finally{setExportBusy(false);paint();}};
let scrollPhase=0;setInterval(()=>{const e=cache[active],r=e?.results[frameIndex%e?.results.length];if(!r)return;const c=$('scrollPreview'),cx=c.getContext('2d');c.width=r.w+32;c.height=r.h;cx.clearRect(0,0,c.width,c.height);cx.drawImage(rgbaCanvas(r.rgb,r.w,r.h,e.jobs[frameIndex%e.results.length].preparedMask),16-(scrollPhase++%8),0);$('scrollInfo').textContent=states[active].scroll?'All8horizontal phases validated: zero cells with more than two colours. This is colour feasibility, not game performance.':'Unconstrained artwork: horizontal movement may clash. Use only as a stationary detail comparison.';},100);

